PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS user_day_state (day_id INTEGER PRIMARY KEY REFERENCES curriculum_days(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN('UPCOMING','AVAILABLE','IN_PROGRESS','COMPLETED','COMPLETED_WITH_GAPS','REST','MISSED','REPAIR_REQUIRED')), started_at TEXT, completed_at TEXT, actual_minutes INTEGER NOT NULL DEFAULT 0 CHECK(actual_minutes>=0), completion_override INTEGER NOT NULL DEFAULT 0 CHECK(completion_override IN(0,1)), override_reason TEXT);
CREATE TABLE IF NOT EXISTS user_block_state (block_id INTEGER PRIMARY KEY REFERENCES curriculum_blocks(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN('NOT_STARTED','IN_PROGRESS','COMPLETE','SKIPPED','DEFERRED','FAILED','REPAIR_REQUIRED')), started_at TEXT, completed_at TEXT, actual_minutes INTEGER NOT NULL DEFAULT 0 CHECK(actual_minutes>=0), note TEXT);
CREATE TABLE IF NOT EXISTS user_dod_state (dod_item_id INTEGER PRIMARY KEY REFERENCES definition_of_done_items(id) ON DELETE CASCADE, is_complete INTEGER NOT NULL DEFAULT 0 CHECK(is_complete IN(0,1)), completed_at TEXT);
CREATE TABLE IF NOT EXISTS learning_logs (day_id INTEGER PRIMARY KEY REFERENCES curriculum_days(id) ON DELETE CASCADE, learned TEXT NOT NULL DEFAULT '', did TEXT NOT NULL DEFAULT '', explain_without_notes TEXT NOT NULL DEFAULT '', confused TEXT NOT NULL DEFAULT '', next_action TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS timers (block_id INTEGER PRIMARY KEY REFERENCES curriculum_blocks(id) ON DELETE CASCADE, state TEXT NOT NULL CHECK(state IN('STOPPED','RUNNING','PAUSED')), accumulated_seconds INTEGER NOT NULL DEFAULT 0 CHECK(accumulated_seconds>=0), started_at TEXT, updated_at TEXT NOT NULL, CHECK((state='RUNNING' AND started_at IS NOT NULL) OR (state<>'RUNNING' AND started_at IS NULL)));
